}

input.new_string:
read_scutil_key() {
  local key="$1"
  scutil --proxy | awk -v k="$key" '{
    for (i = 1; i <= NF; i++) {
      if ($i == k && $(i + 1) == ":") {
        print $(i + 2)
        exit
      }
    }
  }'
}
